// Monthly rows are keyed to the first month of their quarter. The consumers
// sum rows that share a date, so no merging is needed here.
function rollUpToQuarters(
  interval: string,
  data: { assets: QueryDataEntity[]; debts: QueryDataEntity[] },
) {
  if (interval !== 'Quarterly') {
    return data;
  }
  const toQuarter = (row: QueryDataEntity) => ({
    ...row,
    date: monthUtils.quarterFromDate(row.date),
  });
  return { assets: data.assets.map(toQuarter), debts: data.debts.map(toQuarter) };
}

